import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { addComment } from "../handlers/addComment";
import type { ApiError } from "../runtime/client";
import type { AddCommentRequest } from "../types/AddCommentRequest";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePostEntityType } from "../types/SpacePostEntityType";

type Data = Awaited<ReturnType<typeof addComment>>;
type Vars = { spaceId: SpacePartition; discussionSk: SpacePostEntityType; req: AddCommentRequest };

export function useAddComment(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => addComment(vars.spaceId, vars.discussionSk, vars.req),
    ...options,
  });
}
